input.content:
import re
from pathlib import Path

root = Path(".")
targets = ["ai-log", "src"]
files = [Path(p) for p in ["README.md", "relatorio.md", "requirements.txt"]]
for d in targets:
    files += list(Path(d).rglob("*"))

pat = re.compile(r"\bsk-[A-Za-z0-9]{10,}\b|api[_-]?key|apikey|bearer\s+[A-Za-z0-9]|authorization\s*[:=]|secret\s*[:=]|token\s*[:=]\s*[\"'][A-Za-z0-9]{16,}", re.I)

found = []
for f in files:
    if not f.is_file():
        continue
    try:
        data = f.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        continue
    if pat.search(data):
        found.append(str(f))

print("arquivos nao-data com possivel segredo:", found if found else "NENHUM")
